<div class="roles-modo">@if($puedeEditar)<button type="button" class="roles-boton-edicion" :class="$wire.edicionPermisos?'en-edicion':''" :aria-pressed="$wire.edicionPermisos" :title="$wire.edicionPermisos?'Salir y descartar cambios sin guardar':'Habilitar cambios en permisos'" x-on:click="actuar('edicion',()=>$wire.edicionPermisos?$wire.salirEdicion():$wire.habilitarEdicion())" :disabled="!!proceso"><i class="ph-duotone" :class="proceso==='edicion'?'ph-spinner-gap roles-giro':$wire.edicionPermisos?'ph-lock-simple-open':'ph-pencil-simple'" aria-hidden="true"></i><span x-text="$wire.edicionPermisos?'Salir':'Edición'"></span></button>@endif<span class="roles-modo-estado" x-text="$wire.edicionPermisos?'Editando':'Consulta'"></span></div>
